files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  min-block-size: 100dvb;
  margin: 0;
  font-family: var(--main-font-family), sans-serif;
  font-size: var(--main-text-size, 18px);
  background-color: var(--white, #fff);
  background-image: var(--bg-pattern);
}

ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.visually-hidden {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  margin: -1px;
  border: 0;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 2rem;
  background-color: var(--blue);
}

.logo {
  inline-size: 150px;
  font-weight: 800;
  font-size: 38px;
  text-transform: uppercase;
}

.logo__image {
  inline-size: 100%;
}

.menu {
  position: relative;
}

.menu__button {
  display: block;
  inline-size: 50px;
  block-size: 50px;
  border: none;
  background-color: transparent;
  background-image: url(../svg/hamburger-open.svg);
  background-repeat: no-repeat;
  background-size: contain;
  cursor: pointer;
}

.menu__button:hover {
  opacity: 0.6;
}

.menu_opened .menu__button {
  background-image: url(../svg/hamburger-close.svg);
}

.menu__list {
  position: absolute;
  display: none;
  flex-direction: column;
  gap: 0.2em;
  text-align: center;
  inset-block-start: 65px;
  inset-inline-end: 0;
}

.menu_opened .menu__list {
  display: flex;
}

.menu__list a {
  display: block;
  border: 1px solid var(--black);
  padding: 1em 2em;
  color: currentColor;
  font-size: 1.25em;
  text-decoration: none;
  background-color: var(--yellow);
}

.menu a:hover {
  opacity: 0.8;
}
@media (min-width: 768px) {
  .menu__button {
    display: none;
  }

  .menu__list {
    position: static;
    display: flex;
    flex-direction: row;
    gap: 1em;
  }

  .menu__list a {
    border: none;
    padding: initial;
    background-color: transparent;
  }
}
